mod component;

use crate::app::App;
use crate::message::{Message, MessageExt};
use iced::Task;

crate::define_standard_editor! {
    name: wave_ini,
    name_pascal: WaveIni,
    record: dispel_core::WaveIni,
    field: wave_ini_editor,
    file: "Wave.ini",
    extension: {
        message: WaveIniExtension,
        handle: handle_extension,
    },
    title: "Wave INI editor",
}

/// Editor-specific messages. The catalog handling and spreadsheet view are
/// generated by `define_standard_editor!` — this editor only adds WAV export.
#[derive(Debug, Clone)]
pub enum WaveIniExtension {
    ExportWav(usize),
    ExportedWav(Result<String, String>),
}

fn handle_extension(msg: WaveIniExtension, app: &mut App) -> Task<Message> {
    match msg {
        WaveIniExtension::ExportWav(index) => {
            if app.state.shared_game_path.is_empty() {
                app.state.editors.wave_ini_editor.status_msg =
                    "Please select game path first.".into();
                return Task::none();
            }
            if let Some((_, wave)) = app.state.editors.wave_ini_editor.filtered.get(index) {
                let snf_filename = match &wave.snf_filename {
                    Some(f) => f.clone(),
                    None => {
                        app.state.editors.wave_ini_editor.status_msg =
                            "No SNF filename for this entry.".into();
                        return Task::none();
                    }
                };
                let stem = std::path::Path::new(&snf_filename)
                    .file_stem()
                    .map(|s| s.to_string_lossy().to_string())
                    .unwrap_or_else(|| format!("wave_{}", wave.id));
                let game_path = app.state.shared_game_path.clone();
                app.state.editors.wave_ini_editor.loading_state =
                    crate::components::loading_state::LoadingState::Loading;
                return Task::perform(
                    async move {
                        let handle = rfd::AsyncFileDialog::new()
                            .set_file_name(format!("{}.wav", stem))
                            .add_filter("WAV Audio", &["wav"])
                            .save_file()
                            .await;
                        match handle {
                            Some(h) => {
                                let output_path = h.path().to_path_buf();
                                if let Some(parent) = output_path.parent()
                                    && let Err(e) = std::fs::create_dir_all(parent)
                                {
                                    return Err(format!(
                                        "Failed to create output directory: {}",
                                        e
                                    ));
                                }
                                let snf_path =
                                    crate::platform::find_snf_file(&game_path, &snf_filename);
                                dispel_core::snf::extract(&snf_path, &output_path)
                                    .map(|_| output_path.to_string_lossy().to_string())
                                    .map_err(|e| e.to_string())
                            }
                            None => Err("Export cancelled".into()),
                        }
                    },
                    |result| {
                        Message::wave_ini(WaveIniEditorMessage::Extension(
                            WaveIniExtension::ExportedWav(result),
                        ))
                    },
                );
            }
            Task::none()
        }
        WaveIniExtension::ExportedWav(result) => {
            app.state.editors.wave_ini_editor.loading_state =
                crate::components::loading_state::LoadingState::Loaded(());
            match result {
                Ok(p) => {
                    app.state.editors.wave_ini_editor.status_msg = format!("Exported to {}", p)
                }
                Err(e) => {
                    app.state.editors.wave_ini_editor.status_msg = format!("Export failed: {}", e)
                }
            }
            Task::none()
        }
    }
}
